import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ComplianceService } from '../../services/compliance.service';
import { AuditLog, HighValueTransaction, NotificationItem } from '../../models/audit.model';

@Component({
  selector: 'app-compliance',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './compliance.component.html',
  styleUrls: ['./compliance.component.css']
})
export class ComplianceComponent implements OnInit {
  flaggedTransactions: HighValueTransaction[] = [];
  auditLogs: AuditLog[] = [];
  notifications: NotificationItem[] = [];

  alertMessage: string | null = null;
  alertType: string = 'info';

  constructor(private complianceService: ComplianceService) {}

  ngOnInit(): void {
    this.loadAll();
  }

  loadAll(): void {
    this.loadFlaggedTransactions();
    this.loadAuditLogs();
    this.loadNotifications();
  }

  loadFlaggedTransactions(): void {
    this.complianceService.getFlaggedTransactions().subscribe({
      next: (res) => {
        this.flaggedTransactions = res.data || res || [];
      },
      error: (err) => console.error(err)
    });
  }

  loadAuditLogs(): void {
    this.complianceService.getAuditLogs().subscribe({
      next: (res) => {
        this.auditLogs = res.data || res || [];
      },
      error: (err) => console.error(err)
    });
  }

  loadNotifications(): void {
    this.complianceService.getCustomerNotifications(1).subscribe({
      next: (res) => {
        this.notifications = res.data || res || [];
      },
      error: (err) => console.error(err)
    });
  }

  reviewTransaction(flagId: number): void {
    const remarks = prompt('Enter compliance review remarks:') || 'Verified legitimate financial transaction.';
    this.complianceService.reviewTransaction(flagId, remarks).subscribe({
      next: () => {
        this.alertMessage = `High-value transaction #${flagId} reviewed and cleared!`;
        this.alertType = 'success';
        this.loadFlaggedTransactions();
      },
      error: (err) => {
        this.alertMessage = err?.error?.errorMessage || 'Review action failed.';
        this.alertType = 'danger';
      }
    });
  }

  markRead(notificationId: number): void {
    this.complianceService.markNotificationRead(notificationId).subscribe({
      next: () => {
        this.loadNotifications();
      },
      error: (err) => console.error(err)
    });
  }
}
<div class="container py-4">
  <!-- Page Header -->
  <div class="d-flex justify-content-between align-items-center mb-4 pb-2 border-bottom">
    <div>
      <h2 class="fw-bold mb-1"><i class="bi bi-shield-check text-danger me-2"></i>Audit, Compliance & Event Notifications</h2>
      <p class="text-secondary mb-0">Module 6: AML high-value transaction surveillance (&ge; $10k), regulatory audit trail, and customer alerts (US-17, US-18, US-19)</p>
    </div>
    <span class="badge bg-danger-subtle text-danger border border-danger-subtle px-3 py-2 rounded-pill">
      Port 8087: audit-notification-service
    </span>
  </div>

  <!-- Alert Banner -->
  <div *ngIf="alertMessage" [class]="'alert alert-' + alertType + ' alert-dismissible fade show shadow-sm'" role="alert">
    <i class="bi bi-info-circle me-2"></i>{{ alertMessage }}
    <button type="button" class="btn-close" (click)="alertMessage = null"></button>
  </div>

  <div class="row g-4 mb-4">
    <!-- 1. Real-Time Customer Notifications Badge & Feed (US-19) -->
    <div class="col-lg-5">
      <div class="card h-100 shadow-sm border-0 bg-white">
        <div class="card-header bg-navy text-white py-3 d-flex justify-content-between align-items-center">
          <h5 class="mb-0 fw-semibold"><i class="bi bi-bell me-2 text-warning"></i>1. Customer Event Alerts (US-19)</h5>
          <span class="badge bg-warning text-dark">{{ notifications.length }} Alerts</span>
        </div>
        <div class="card-body p-3 overflow-auto" style="max-height: 400px;">
          <div *ngFor="let notif of notifications" class="p-3 mb-2 rounded-3 border" [ngClass]="notif.isRead ? 'bg-light' : 'bg-white border-warning'">
            <div class="d-flex justify-content-between align-items-center mb-1">
              <span class="badge" [ngClass]="{
                'bg-success-subtle text-success-emphasis': notif.type === 'DISCOUNT' || notif.type === 'CREDIT',
                'bg-danger-subtle text-danger-emphasis': notif.type === 'DEBIT',
                'bg-primary-subtle text-primary-emphasis': notif.type === 'LOAN',
                'bg-warning-subtle text-warning-emphasis': notif.type === 'ALERT'
              }">{{ notif.type }}</span>
              <span class="small text-muted" *ngIf="notif.isRead"><i class="bi bi-check2-all text-success"></i> Read</span>
              <button class="btn btn-sm btn-link text-decoration-none p-0" *ngIf="!notif.isRead" (click)="markRead(notif.notificationId!)">Mark read</button>
            </div>
            <div class="fw-bold text-dark">{{ notif.title }}</div>
            <p class="small text-secondary mb-0 mt-1">{{ notif.message }}</p>
          </div>
          <div *ngIf="notifications.length === 0" class="text-center py-4 text-muted">
            No active event notifications.
          </div>
        </div>
      </div>
    </div>

    <!-- 2. AML High-Value Surveillance Monitoring (US-17) -->
    <div class="col-lg-7">
      <div class="card h-100 shadow-sm border-0 bg-white">
        <div class="card-header bg-navy text-white py-3 d-flex justify-content-between align-items-center">
          <h5 class="mb-0 fw-semibold"><i class="bi bi-exclamation-octagon me-2 text-danger"></i>2. High-Value Surveillance Feed (&ge; $10k) (US-17)</h5>
          <button class="btn btn-sm btn-outline-light" (click)="loadFlaggedTransactions()">
            <i class="bi bi-arrow-clockwise"></i>
          </button>
        </div>
        <div class="card-body p-0 table-responsive">
          <table class="table table-hover align-middle mb-0">
            <thead class="table-light">
              <tr>
                <th>Flag ID</th>
                <th>Source Acc</th>
                <th>Destination</th>
                <th>Amount</th>
                <th>Review Status</th>
                <th class="text-end">Action</th>
              </tr>
            </thead>
            <tbody>
              <tr *ngFor="let tx of flaggedTransactions">
                <td class="fw-bold">#{{ tx.flagId }}</td>
                <td><code>{{ tx.sourceAccount }}</code></td>
                <td><code>{{ tx.destinationAccount || 'N/A' }}</code></td>
                <td class="fw-bold text-danger">${{ tx.amount | number:'1.2-2' }}</td>
                <td>
                  <span class="badge" [ngClass]="tx.reviewed ? 'bg-success-subtle text-success-emphasis' : 'bg-danger-subtle text-danger-emphasis'">
                    {{ tx.reviewed ? 'REVIEWED' : 'UNREVIEWED' }}
                  </span>
                </td>
                <td class="text-end">
                  <button class="btn btn-sm btn-outline-primary" *ngIf="!tx.reviewed" (click)="reviewTransaction(tx.flagId!)">
                    <i class="bi bi-shield-check"></i> Review
                  </button>
                  <span class="small text-muted" *ngIf="tx.reviewed">Cleared</span>
                </td>
              </tr>
              <tr *ngIf="flaggedTransactions.length === 0">
                <td colspan="6" class="text-center py-4 text-muted">No high-value surveillance flags found.</td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>
    </div>
  </div>

  <!-- 3. Regulatory Immutable Audit Log (US-18) -->
  <div class="card shadow-sm border-0 bg-white">
    <div class="card-header bg-navy text-white py-3 d-flex justify-content-between align-items-center">
      <h5 class="mb-0 fw-semibold"><i class="bi bi-journal-text me-2 text-info"></i>3. Regulatory Audit Trail Inspection (US-18)</h5>
      <button class="btn btn-sm btn-outline-light" (click)="loadAuditLogs()">
        <i class="bi bi-arrow-clockwise me-1"></i>Refresh Log
      </button>
    </div>
    <div class="card-body p-0 table-responsive">
      <table class="table table-hover align-middle mb-0">
        <thead class="table-light">
          <tr>
            <th>Audit ID</th>
            <th>User ID</th>
            <th>Role</th>
            <th>Action</th>
            <th>Resource Ref</th>
            <th>Details / Justification</th>
            <th>IP Address</th>
          </tr>
        </thead>
        <tbody>
          <tr *ngFor="let log of auditLogs">
            <td class="fw-bold">#{{ log.auditId }}</td>
            <td><i class="bi bi-person me-1"></i>{{ log.userId }}</td>
            <td><span class="badge bg-secondary-subtle text-secondary-emphasis">{{ log.userRole }}</span></td>
            <td><span class="badge bg-primary-subtle text-primary-emphasis">{{ log.action }}</span></td>
            <td><code>{{ log.resourceId || 'N/A' }}</code></td>
            <td class="small">{{ log.details }}</td>
            <td class="small text-muted">{{ log.clientIpAddress }}</td>
          </tr>
          <tr *ngIf="auditLogs.length === 0">
            <td colspan="7" class="text-center py-4 text-muted">No audit log records found.</td>
          </tr>
        </tbody>
      </table>
    </div>
  </div>
</div>
